-- Aaptiv — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'aaptiv.com' OR LOWER(`name`) = LOWER('Aaptiv'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Aaptiv', NULL, 'https://aaptiv.com', NULL, NULL, 'Корпоративна програма здоров''я й фітнесу для працівників: доступ до мережі тисяч спортзалів і студій, понад 10 000 занять на вимогу, тренування, складені штучним інтелектом, а також медитації й програми турботи про здоров''я.', 'A corporate health and fitness benefit for employees: access to a network of thousands of gyms and studios, 10,000+ on-demand classes, AI-designed routines, plus meditation and wellbeing programs.', 'Aaptiv — комплексна програма благополуччя, яку компанії пропонують своїм працівникам як бонус. Вона допомагає людям рухатися до особистих цілей — від спокою й усвідомленості до марафону. Працівники отримують доступ до фітнес-мережі Aaptiv з тисячами спортзалів і студій, понад 10 000 занять на вимогу та тренування, складені штучним інтелектом, з підказками щодо засвоєння нових технік. Окрім тренувань, є медитації й вправи на усвідомленість, а також клінічно перевірені програми: допомога при болях опорно-рухового апарату й відновленні, програми до й після пологів, супровід під час прийому препаратів GLP-1, ресурси щодо стресу, сну й харчування. Для компаній доступна демонстрація.', 'Aaptiv is a complete employee wellness benefit that companies offer their staff. It helps people make progress toward personal goals, from mindfulness to marathons. Employees get access to Aaptiv''s fitness network of thousands of gyms and studios, more than 10,000 on-demand classes, and AI-designed routines with guidance for mastering new techniques. Beyond workouts there are guided meditations and mindfulness exercises, as well as clinically validated care: support for musculoskeletal pain and recovery, pre- and postnatal programs, a GLP-1 companion program, and resources on stress, sleep and nutrition. Companies can schedule a demo.', 'Доступ до тисяч спортзалів і студій
Понад 10 000 занять на вимогу
Тренування, складені штучним інтелектом
Медитації й вправи на усвідомленість
Програми при болях і для відновлення
Програми до й після пологів
Ресурси щодо сну, стресу й харчування', 'Access to thousands of gyms and studios
10,000+ on-demand classes
AI-designed routines
Meditation and mindfulness exercises
Programs for pain and recovery
Pre- and postnatal programs
Resources on sleep, stress and nutrition', 'Компанії, які шукають фітнес- і велнес-бонус для працівників, і HR-команди.', 'Companies looking for a fitness and wellness benefit for employees, and HR teams.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'aaptiv.com' OR LOWER(`name`) = LOWER('Aaptiv')) ORDER BY `id` LIMIT 1);
