INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Aaptiv is a complete employee wellness benefit that companies offer their staff. It helps people make progress toward personal goals, from mindfulness to marathons. Employees get access to Aaptiv''s fitness network of thousands of gyms and studios, more than 10,000 on-demand classes, and AI-designed routines with guidance for mastering new techniques. Beyond workouts there are guided meditations and mindfulness exercises, as well as clinically validated care: support for musculoskeletal pain and recovery, pre- and postnatal programs, a GLP-1 companion program, and resources on stress, sleep and nutrition. Companies can schedule a demo.', 'manual' FROM DUAL WHERE @new = 1;
