-- Alpha Progression — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'alphaprogression.com' OR LOWER(`name`) = LOWER('Alpha Progression'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Alpha Progression', NULL, 'https://alphaprogression.com', NULL, NULL, 'Застосунок для силових тренувань: генерує науково обґрунтовану програму під ваші цілі й обладнання, для кожного підходу називає точну вагу й кількість повторень за вашими результатами, має 795 відеоінструкцій і детальні графіки прогресу.', 'A strength training app: it generates a science-backed program for your goals and equipment, gives an exact weight and rep target for every set based on your results, and has 795 exercise videos and detailed progress charts.', 'Alpha Progression допомагає набирати м''язи й силу за планом, складеним саме для вас. Генератор програм враховує цілі, обладнання, частоту й тривалість тренувань і будує науково обґрунтовану програму з 795 вправ — спліт «жим-тяга-ноги», «верх-низ», фулбоді чи інший під ваш тиждень. Програму можна змінювати як завгодно, обираючи м''язи для пріоритету. Алгоритм для кожного підходу називає точну вагу, кількість повторень і інтенсивність на основі того, що ви реально підняли, щоб навантаження було складним, але не надмірним, і не виникало плато. Бібліотека вправ знята сертифікованими тренерами в справжньому залі з поясненням підготовки, виконання й типових помилок. Графіки показують прогрес за вправами, м''язами й замірами тіла. Є калькулятор дисків і розминки, кілька залів, облік резерву повторень і розвантажувальних тижнів.', 'Alpha Progression helps you build muscle and strength with a plan made for you. The plan generator takes into account your goals, equipment, training frequency and duration and builds a science-backed program from 795 exercises, whether Push Pull Legs, Upper Lower, Full Body or another split that fits your week. You can customize anything and prioritize the muscles you want to focus on. For every set the algorithm gives a precise weight, rep count and intensity target based on what you actually lifted, so training is challenging but not overreaching and you avoid plateaus. The exercise library is filmed by certified trainers in a real gym, covering setup, execution and common mistakes. Charts show progress for exercises, muscles and body measurements. There are plate and warmup calculators, multiple gyms, reps in reserve tracking and deloads.', 'Генератор персональних програм
Точні рекомендації ваги й повторень для кожного підходу
795 вправ із відео від тренерів
Графіки прогресу й замірів тіла
Калькулятори дисків і розминки
Кілька залів з різним обладнанням
Періодизація й розвантажувальні тижні', 'Personal program generator
Exact weight and rep targets for every set
795 exercises with trainer videos
Progress and body measurement charts
Plate and warmup calculators
Multiple gyms with different equipment
Periodization and deloads', 'Люди, які займаються силовими тренуваннями й хочуть планомірно нарощувати м''язи й силу — від новачків до досвідчених атлетів.', 'People who strength train and want to build muscle and strength systematically, from beginners to experienced lifters.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
