SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'coachify.ai' OR LOWER(`name`) = LOWER('Coachify'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Coachify', NULL, 'https://coachify.ai', NULL, NULL, 'AI-персональний тренер у застосунку: складає план тренувань під ваші цілі, графік і обладнання, записує кожен підхід і порівнює з вашими середніми результатами, поступово підвищує навантаження й веде облік калорій та харчування за фото.', 'An AI personal trainer in an app: it builds a workout plan for your goals, schedule and equipment, logs every set and compares it with your average, applies progressive overload and tracks calories and nutrition from photos.', 'Coachify поєднує в одному застосунку персонального тренера, журнал тренувань і лічильник калорій. Штучний інтелект складає план тренувань під ваші цілі, розклад і доступне обладнання та поступово підвищує ваги й повторення у правильному темпі. Застосунок пам''ятає все, що ви піднімали, порівнює кожен підхід із вашими середніми показниками й одразу показує прогрес у відсотках. Є тижневий календар і серії тренувань, підрахунок спалених калорій, хвилин і підходів. Під час тренування допомагають розумні таймери відпочинку, 3D-візуалізація вправ для правильної техніки, попередні записи й альтернативні вправи. Розділ харчування показує калорії, макроелементи, кроки й витрачену енергію, а прийом їжі можна записати за кілька секунд за фото. AI-тренер цілодобово відповідає на запитання про техніку, план і харчування.', 'Coachify combines a personal trainer, a workout log and a calorie counter in one app. The AI builds a workout plan around your goals, schedule and available equipment and nudges your weights and reps up at the right pace. The app remembers everything you lift, compares each set against your average and instantly shows your gains as a percentage. There is a weekly calendar with streaks, plus calories burned, minutes and total sets for each workout. During training, smart rest timers, 3D exercise visuals for correct form, past logs and alternative exercises help you know what to do next. The nutrition section shows calories, macros, steps and energy burned, and you can log a meal in seconds with a photo. The AI trainer answers questions about form, plans and nutrition around the clock.', 'Персональний план тренувань від AI
Запис кожного підходу й порівняння з середнім
Автоматичне поступове підвищення навантаження
3D-візуалізація вправ
Розумні таймери відпочинку
Облік калорій і макроелементів за фото
AI-тренер, доступний цілодобово', 'Personal AI workout plan
Logging every set and comparing with your average
Automatic progressive overload
3D exercise visuals
Smart rest timers
Calorie and macro tracking from photos
AI trainer available 24/7', 'Люди, які тренуються в залі й хочуть мати тренера, журнал тренувань і облік харчування в одному застосунку.', 'Gym-goers who want a trainer, a workout log and nutrition tracking in one app.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
