INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'FORM', NULL, 'https://formswim.com', NULL, NULL, 'Розумні окуляри для плавання із застосунком: показують ваші дані просто під час запливу, самі рахують басейни, підходи й інтервали, а персональний тренер HeadCoach підказує, що робити далі, і допомагає бачити реальний прогрес.', 'Smart swim goggles with an app: they show your data while you swim, count laps, sets and intervals for you, and the HeadCoach personal coach tells you what to do next.', 'FORM — розумні окуляри для плавання разом із застосунком, які роблять тренування в басейні цікавішими й зрозумілішими для плавців будь-якого рівня. Дані відображаються прямо перед очима під час запливу, тож тренування стає схожим на гру: можна кидати собі виклик і бачити, як покращуються показники. Окуляри самі рахують басейни, підходи й інтервали, тож не треба тримати все в голові й можна зосередитися на плаванні. Персональний тренер HeadCoach у преміум-підписці дає чіткі покрокові вказівки, що робити далі, і допомагає бачити реальний прогрес. Нова модель — Smart Swim 2 LT. Окуляри продаються в онлайн-магазині й у партнерських магазинах.', 'FORM is a pair of smart swim goggles paired with an app that makes pool workouts more engaging and purposeful for swimmers of any level. Your data appears right in front of your eyes as you swim, turning the session into a game-like experience where you can challenge yourself and watch your stats improve. The goggles count laps, sets and intervals, so you don''t have to keep track and can focus on swimming. HeadCoach, a one-on-one swim coach in the premium subscription, gives clear step-by-step directions on what to do next and helps you see real progress. The newest model is Smart Swim 2 LT. The goggles are sold online and through retail partners.', 'Показ даних у реальному часі під час запливу
Автоматичний підрахунок басейнів, підходів та інтервалів
Персональний тренер HeadCoach
Застосунок для плавання
Відстеження прогресу
Модель окулярів Smart Swim 2 LT', 'Real-time data while you swim
