SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gravl.ai' OR LOWER(`name`) = LOWER('Gravl'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Gravl', NULL, 'https://gravl.ai', NULL, NULL, 'Застосунок для силових тренувань, який сам планує кожне тренування: складає персональний план під ваші цілі, обладнання й графік, автоматично підвищує ваги щотижня, показує відео вправ і враховує відновлення м''язів.', 'A strength training app that plans every workout for you: it builds a personal plan for your goals, equipment and schedule, raises weights automatically each week, shows exercise videos and accounts for muscle recovery.', 'Gravl складає персональний план силових тренувань під ваші цілі, обладнання й розклад — план налаштовує штучний інтелект, а підтримують його живі тренери. Кожне тренування вже розплановане: вправи, підходи, повторення й ваги. Записати підхід можна одним дотиком, бо повторення й вага вже заповнені, після чого запускається таймер відпочинку. Застосунок відстежує кожен підхід і автоматично коригує ваги на наступний тиждень, тож не треба вести таблиці чи гадати. Для кожної вправи є зрозуміле відео з технікою. Gravl відстежує відновлення м''язів, зокрема через інтеграцію з Apple Health, адаптує тренування до залу, в якому ви зараз, і показує зростання вашого показника сили. Запитання щодо застосунку чи тренувань можна поставити тренерам прямо в чаті. Почати можна безкоштовно.', 'Gravl builds a personalized strength training plan around your goals, equipment and schedule; the plan is dialed in by AI and backed by real coaches. Every session is already planned: exercises, sets, reps and weights. You log a set with one tap because reps and weight are prefilled, and the rest timer starts. The app tracks every set and adjusts next week''s weights automatically, so there are no spreadsheets and no guessing. Every exercise has a clear how-to video. Gravl tracks muscle recovery, including through Apple Health, adapts workouts to the gym you are in and shows your growing Strength Score. You can message coaches in the app about app tips or workout advice. Getting started is free.', 'Персональний план під цілі, обладнання й графік
Автоматичне підвищення ваг щотижня
Запис підходу одним дотиком і таймер відпочинку
Відео з технікою для кожної вправи
Відстеження відновлення м''язів
Підтримка тренерів у чаті
Показник сили й прогрес', 'Personal plan for your goals, equipment and schedule
Automatic weekly weight increases
One-tap set logging and rest timer
Form video for every exercise
Muscle recovery tracking
Coach support via chat
Strength Score and progress', 'Люди, які займаються силовими тренуваннями в залі й хочуть готовий план без самостійного планування.', 'People who strength train in the gym and want a ready plan without planning it themselves.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
