SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'joinladder.com' OR LOWER(`name`) = LOWER('Ladder'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Ladder', NULL, 'https://joinladder.com', NULL, NULL, 'Застосунок силових тренувань: щодня готове тренування від професійного тренера, щотижня нові заняття, відеодемонстрації й голосові підказки, облік підходів і ваги, рекорди та журнал харчування в одному місці.', 'A strength training app: a ready workout from a pro coach every day, new sessions each week, video demos and in-ear coaching, rep and weight tracking, personal records and a nutrition log all in one place.', 'Ladder — застосунок для силових тренувань для зайнятих людей, які не хочуть самі планувати заняття. Ви обираєте команду з тренером під свої цілі — пілатес і силові, функціональний тренінг, бодібілдинг, тренування з гантелями чи програму для початківців — і щодня отримуєте готове тренування, а щотижня — нові. Виконувати їх можна вдома, у залі чи на вулиці. Застосунок підказує темп, показує відео вправ і веде голосом прямо під час заняття. Повторення й вага записуються автоматично, рекорди відзначаються, є журнал тренувань і швидкий облік харчування. У командних чатах тренер відповідає на запитання й мотивує. Є 7-денний безкоштовний період без прив''язки картки, підключення Apple Watch і музичних сервісів.', 'Ladder is a strength training app for busy people who don''t want to plan their own workouts. You pick a team led by a coach that matches your goals, such as pilates and strength, functional training, bodybuilding, dumbbell-only training or a beginner program, and get a ready workout every day with new ones each week. You can train at home, at the gym or outdoors. The app sets the pace, shows video demos and coaches you by voice during the session. Reps and weights are logged, personal records are flagged, and there is a training journal plus quick meal logging. In team chats the coach answers questions and keeps you motivated. There is a 7-day free trial with no card required, and it connects to Apple Watch and music services.', 'Щоденний план тренувань від тренера
Понад 5 нових тренувань щотижня
Відеодемонстрації й голосовий супровід
Облік повторень, ваги й особистих рекордів
Журнал харчування
Командні чати з тренером
Підключення Apple Watch і музики', 'Daily workout plan from a coach
5+ new workouts every week
Video demos and in-ear coaching
Rep, weight and PR tracking
Nutrition log
Team chats with the coach
Apple Watch and music integration', 'Зайняті люди, які хочуть регулярно займатися силовими тренуваннями вдома чи в залі без самостійного планування.', 'Busy people who want to do strength training regularly at home or in the gym without planning it themselves.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
