INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Ladder is a strength training app for busy people who don''t want to plan their own workouts. You pick a team led by a coach that matches your goals, such as pilates and strength, functional training, bodybuilding, dumbbell-only training or a beginner program, and get a ready workout every day with new ones each week. You can train at home, at the gym or outdoors. The app sets the pace, shows video demos and coaches you by voice during the session. Reps and weights are logged, personal records are flagged, and there is a training journal plus quick meal logging. In team chats the coach answers questions and keeps you motivated. There is a 7-day free trial with no card required, and it connects to Apple Watch and music services.', 'manual' FROM DUAL WHERE @new = 1;
