INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Peloton combines home exercise equipment with a large class library. The lineup includes Tread treadmills, Bike exercise bikes and the Row rower. Peloton IQ takes away the guesswork: you choose a goal, such as more strength or endurance, and get a personalized weekly plan that adapts to your progress. More than 10,000 classes are available across over 15 workout types, including running, walking, strength, yoga, Pilates, cycling, boxing and rowing, with instructors for every mood and level. Classes are built around a community that shows up together. The new generation of treadmills, Tread Flex, Tread Vision and Tread+ Vision, lets you run, walk and train at your own pace.', 'manual' FROM DUAL WHERE @new = 1;
