-- Planfit — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'planfit.ai' OR LOWER(`name`) = LOWER('Planfit'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Planfit', NULL, 'https://planfit.ai', NULL, NULL, 'Безкоштовний AI-тренер для початківців у залі: за 30 секунд складає персональний план під ваш рівень, цілі й обладнання, підбирає підходи, повторення й вагу, показує відео вправ і веде голосом під час тренування.', 'A free AI trainer for gym beginners: in 30 seconds it builds a personal plan for your level, goals and equipment, picks sets, reps and weights, shows exercise videos and coaches you by voice during the workout.', 'Planfit — застосунок із персональним AI-тренером, створений насамперед для тих, хто тільки починає ходити в зал. Ви вказуєте рівень підготовки, цілі й доступне обладнання, і менш ніж за 30 секунд отримуєте безкоштовний персональний план. Тренування враховують ваші цілі, силу, попередні заняття й обладнання залу, а кількість підходів, повторень і вагу для кожної вправи підбирає штучний інтелект і коригує з прогресом. Сотні детальних інструкцій із відео пояснюють техніку, які м''язи працюють, поради тренера, альтернативні вправи й навіть як правильно дихати. Голосовий супровід веде вас через кожен підхід і відпочинок. Застосунок автоматично записує кожен підхід, показує зростання сили, серії тренувань і відновлення м''язів.', 'Planfit is an AI personal trainer app built primarily for people who are new to the gym. You enter your fitness level, goals and available equipment, and in under 30 seconds get a free personalized plan. Workouts take into account your goals, strength, past sessions and gym setup, and the AI chooses the sets, reps and weight for every exercise and adjusts them as you progress. Hundreds of detailed video guides explain proper form, which muscles are working, trainer tips, alternatives and even how to breathe. Voice coaching talks you through every set and rest period. The app logs every set automatically and shows your strength gains, workout streaks and muscle recovery.', 'Персональний план від AI за 30 секунд
Підбір підходів, повторень і ваги
Сотні відеоінструкцій із технікою виконання
Голосовий супровід під час тренування
Автоматичний журнал тренувань
Відстеження сили й відновлення м''язів', 'Personal AI plan in 30 seconds
Sets, reps and weight chosen for you
Hundreds of exercise videos on form
Voice coaching during workouts
Automatic workout log
Strength and muscle recovery tracking', 'Початківці в залі, які хочуть тренуватися за готовим планом із підказками щодо техніки.', 'Gym beginners who want to follow a ready plan with guidance on technique.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
