INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Planfit is an AI personal trainer app built primarily for people who are new to the gym. You enter your fitness level, goals and available equipment, and in under 30 seconds get a free personalized plan. Workouts take into account your goals, strength, past sessions and gym setup, and the AI chooses the sets, reps and weight for every exercise and adjusts them as you progress. Hundreds of detailed video guides explain proper form, which muscles are working, trainer tips, alternatives and even how to breathe. Voice coaching talks you through every set and rest period. The app logs every set automatically and shows your strength gains, workout streaks and muscle recovery.', 'manual' FROM DUAL WHERE @new = 1;
